			function resetForm() {
			    // 사용자목록 DS 조회
			    var dsUserList = app.lookup("dsUserList");
			    
			    // 사용자 영역 grp 초기화
			    var grpUserArea = app.lookup("grpUserArea");
			    var grpChildren = grpUserArea.getChildren();
			    if (grpChildren) {
			        grpChildren.forEach(function(ctrl, idx){
			            console.log("resetForm: idx = " + idx);
			        	console.log("resetForm: grpId = " + ctrl.id);
			        	/** @type cpr.controls.Container */
			        	var grpUserItemNode = app.lookup(ctrl.id);
			        	
			        	var children = grpUserItemNode.getChildren();
			        	children.forEach(function(ctrl, idx){
			        		console.log("resetForm: grpItem grpId = " + ctrl.id);
			        		var currOpt = app.lookup(ctrl.id);
			        		currOpt.removeEventListener("click", true);
			        	});
			        	grpUserArea.removeChild(ctrl, true);
			        });
			    }
			    
			    // 사용자목록 초기화
			    dsUserList.clearData();
			    console.log(dsUserList.getRowDataRanged());
			    var rowCnt = util.DataSet.getRowCount(app, "dsUserList");   
			    
			    // 사용자 영역 및 콤보박스 영역 숨기기
			    util.Control.setVisible(app, false, "grpUserArea");
			    var vcGrpLayout = app.lookup("grpData").getLayout();
			    if (vcGrpLayout.isRowVisible(1)) {
			        vcGrpLayout.setRowVisible(1, false);    
			    }
			    
			    // 사용자 권한 상세 영역 초기화
			    var vcGrpDtlLayout = app.lookup("grpDtl").getLayout();
			    vcGrpDtlLayout.setRowVisible(2, true);
			    
			    // 사용자정보 초기화
			    util.DataSet.clear(app, "dsUserInfo");
			    
			    // 컨트롤러 초기화
			    util.Control.reset(app, [
			        "grpData", "grdList", "grdList2", "grpUserArea", "grpCombo",
			        "cmbUnitSystem", "cmbAuthType", 
			        "cmbRgnSido", "cmbRgnSido", "cmbRgnSgg", "cmbRgnInst" 
			    ]);
			    
			    // FormGrp 재갱신
			    util.Control.redraw(app, "grpData");
			}

			/**
			 * 지역 (시/군/구) 존재여부 확인
			 */
			function check_rgnSggExist() {
			    var result = true;
			    var dsSgg = app.lookup("dsSgg");
			    dsSgg.getRowDataRanged().forEach(function(row){
			        var sggNm = row["SGG_NM"];
			        if (sggNm.indexOf("*") >= 0) {
			            result = false;
			        }
			    });
			    
			    return result;
			}

			/**
			 * 시도 및 시도수행기관 검색여부 확인
			 */
			function check_srchSidoInst() {
			    var result = false;
			    
			    var dsSido = app.lookup("dsSido");
			    dsSido.getRowDataRanged().forEach(function(row){
			        // 기관유형구분코드 목록에서 시도 및 시도수행기관 찾기
			        var instTypeSeCds = row["INST_TYPE_SE_CDS"];
			        var arr = instTypeSeCds.split("|");    // 구분자로 분할하여기관유형구분코드 목록 만들기
			        var findSidoInstCds = arr.filter(function(code){
			            return code == "2" || code == "5";
			        });
			        result = (findSidoInstCds != undefined);
			    });
			    
			    return result;
			}

