			/**
			 * 권한상세 문구 생성
			 * 
			 * @param {cpr.data.Row} poRow  선택된 로우
			 */
			function makeAuthDtlText(poRow) {
			    // 변수 초기화
			    var dtlText = "";
			    var condition = "";
			    
			    // 시도 선택 여부
			    var bSelectSido = true;
			    // 시군구 선택 여부
			    var bSelectSgg = true;
			    // 기관 선택 여부
			    var bSelectInst = true;
			    
			    var untTaskwkSeCd = poRow["UNT_TASKWK_SE_CD"];
			    console.log("=== 단위업무구분코드:", untTaskwkSeCd);
			    var ctpvCd = ValueUtil.fixNull(poRow["CTPV_CD"]);
			    console.log("=== 시도코드:", ctpvCd);
			    var sggCd = ValueUtil.fixNull(poRow["SGG_CD"]);
			    console.log("=== 시군구코드:", sggCd);
			    var instNo = ValueUtil.fixNumber(poRow["INST_NO"]);
			    console.log("=== 기관번호:", instNo);
			    
			    // 전체기관일때 처리
			    if (instNo == 0) {
			        bSelectInst = false;
			        
			        // 시도가 전체 (A) 인경우 전체로 표시 
			        if (ctpvCd == "A") {
			            bSelectSido = false;
			            bSelectSgg = false;
			        } else {
			            // 시도가 선택되어 있고 시군구가 전체 (A) 인경우 전체로 표시 
			            if (sggCd == "A") {
			                bSelectSgg = false;
			            }
			        }
			    } else {
			        // 기관번호 존재한 경우 (시도수행기관) 
			        if (ctpvCd != "A" && sggCd == "A") {
			            bSelectSgg = false;
			        }
			    }
			    
			    var ctpvNm = "전체";
			    var sggNm = "전체";
			    // 1) 시도명 검색
			    if (bSelectSido) {
			        condition = "UNT_TASKWK_SE_CD == '" + untTaskwkSeCd
			                    + "' && CTPV_CD == '" + ctpvCd
			                    + "'";
			        ctpvNm = util.DataSet.getFindRowValue(app, "dsRgnInstList", condition, "CTPV_NM");
			        
			        // 2) 시군구명 검색
			        if (bSelectSgg) {
			            condition = "UNT_TASKWK_SE_CD == '" + untTaskwkSeCd
			                    + "' && CTPV_CD == '" + ctpvCd
			                    + "' && SGG_CD == '" + sggCd    
			                    + "'";
			            sggNm = util.DataSet.getFindRowValue(app, "dsRgnInstList", condition, "SGG_NM");
			        }
			    }
			    
			    // 3) 기관명 검색
			    var instNm = "전체";
			    if (bSelectInst) {
			        if (bSelectSgg) {
			            // 시군구수행기관인 경우
			            condition = "UNT_TASKWK_SE_CD == '" + untTaskwkSeCd
			                + "' && CTPV_CD == '" + ctpvCd
			                + "' && SGG_CD == '" + sggCd
			                + "' && INST_NO == '" + instNo
			                + "'";    
			        } else {
			            // 시도수행기관인 경우
			            condition = "UNT_TASKWK_SE_CD == '" + untTaskwkSeCd
			                + "' && CTPV_CD == '" + ctpvCd
			                + "' && INST_NO == '" + instNo
			                + "'"; 
			        }
			        
			        instNm = util.DataSet.getFindRowValue(app, "dsRgnInstList", condition, "INST_NM");
			    }
			    
			    // 권한상세 문구 설정
			    if (ctpvNm == "전체") {
			        // 시도 전체선택시
			        dtlText = ctpvNm;
			    } else {
			        // 시군구수행기관인 경우
			        if (bSelectSgg) {
			            dtlText = ctpvNm + " > " + sggNm + " > " + instNm;
			        } else {
			            // 시도수행기관인 경우
			            dtlText = ctpvNm + " > " + instNm;
			        }
			        
			    }
			    
			    return dtlText;
			}

