			/*
			 * 루트 컨테이너에서 load 이벤트 발생 시 호출.
			 * 앱이 최초 구성된후 최초 랜더링 직후에 발생하는 이벤트 입니다.
			 */
			function onBodyLoad(/* cpr.events.CEvent */ e){
			    // 접속 서버 정보 조회후 개발모드 선택
			    var profile = util.Auth.getUserInfo(app, "PROFILE");
			    mbDevMode = (profile == "local" || profile == "dev2") ? true : false;
			    console.log("=== onBodyLoad: mbDevMode=" + mbDevMode);
			    
			    // 콤보박스 영역 숨기기
			    var vcGrpLayout = app.lookup("grpData").getLayout();
			    vcGrpLayout.setRowVisible(1, false);
			    
			    // 사용자 권한 상세 영역 숨기기
			    vcGrpLayout.setColumnVisible(1, false);

				// 화면 구성시 필요한 데이터 조회
				util.Submit.send(app, "subOnLoad", function(pbSuccess){
					if(pbSuccess){
			            if (mbDevMode) {
			                /** @type cpr.data.DataMap */
			                var userInfo = util.Auth.getUserInfo(app);
			                console.log("=== 사용자 정보:", userInfo.getDatas());
			                
			                /** @type cpr.data.DataMap */
			                var selectSysCd = util.Auth.getSelectSysCd(app);        // 현재 선택된 시스템코드
			                console.log("=== 현재 선택된 시스템코드:", selectSysCd);
			                
			                var groupAuthrtCd = util.Auth.getUserInfo(app, "GROUP_AUTHRT_SE_CD");
			                console.log("=== 부여된 그룹권한구분코드: " + groupAuthrtCd);
			            
			                // 초기데이터 OnLoad - 테스트용 단위업무별 권한 정보
			                // :: 단위업무구분코드가 U14 (업무공통), U15 (시스템관리) 인 경우 테스트용 단위업무 (지자체청소년안전망) 로 설정
			                var _untTaskwkSeCd = userInfo.getValue("UNT_TASKWK_SE_CD");
			                if (_untTaskwkSeCd == "U14" || _untTaskwkSeCd == "U15") {
			                    util.DataMap.setValue(app, "dmSearch", "UNT_TASKWK_SE_CD", "U01");
			                } else {
			                    util.DataMap.setValue(app, "dmSearch", "UNT_TASKWK_SE_CD", _untTaskwkSeCd);
			                }
			                util.DataMap.setValue(app, "dmSearch", "AUTHRT_TYPE_SE_CD", "01");    // 지역별 권한
			                
			                // 권한상세표시여부 (우측 그리드 화면)
			                var psAuthDtlViewYn = vcGrpLayout.isColumnVisible(1) ? "Y" : "N";
			                util.DataMap.setValue(app, "dmSearch", "AUTH_DTL_VIEW_YN", psAuthDtlViewYn);
			                
			                util.Submit.send(app, "subOnLoad2", function(pbSuccess){
			                    if(pbSuccess) {
			                        util.DataMap.reset(app, "dmSearch");
			                        app.lookup("grpData").redraw();
			                    }
			                });
			            } else {
			                app.lookup("grpData").redraw();
			            }
					}
				});
			}

