			/*
			 * "권한등록" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e){
			    var btnSave = e.control;
			    
			    // Validation 체크
			    var rowCnt = util.DataSet.getRowCount(app, "dsUserList");
			    if (rowCnt == 0) {
			        var label = util.Control.getProperty(app, "grpUserArea", "fieldLabel");
			        util.Msg.alert(app, "WRN-M013", label, null, "알림");
			        return;
			    }
			    
			    rowCnt = util.DataSet.getRowCount(app, "dsAuthList");
			    if (rowCnt == 0) {
			        var label = util.Control.getProperty(app, "grdList", "fieldLabel");
			        util.Msg.alert(app, "WRN-M013", label, null, "알림");
			        return;
			    }
			    
			    var dsAuthList = app.lookup("dsAuthList");
			    
			    // 그리드: UNCHANGED 상태를 INSERTED 로 변환
			    for (var idx = 0; idx < rowCnt; idx++) {
			        dsAuthList.setRowState(idx, RowState.INSERTED);
			    }
			    console.log(dsAuthList.getRowDataRanged());
			    
			    var dsUserList = app.lookup("dsUserList");
			    var insCnt = dsUserList.getRowStatedCount(RowState.INSERTED);
			    console.log(insCnt);
			    console.log(dsUserList.getRowDataRanged());
			    
			    doSave();
			}

